/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/types\\/events\"}],\"author\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/users\\/8\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media\\/3086\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media?parent=2117\"}],\"wp:term\":[{\"taxonomy\":\"event_categories\",\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/event_categories?post=2117\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}',1,'2023-10-05 04:52:01','2023-10-05 04:52:01'),(59,'Kanab Christmas Light Parade and Festival','vsu','1804',162,'2023&#8217;s Theme: Cowboy Christmas\nThanksgiving weekend we have the Christmas Light Parade and Festival. This is the best kickoff to the holiday season you will find anywhere in Southern Utah!\n\nWe will have a short tree lighting ceremony and then shut down the highway and begin our unique Christmas Light Parade.\nAnyone can enter a vehicle or float in the parade. If you wish to enter the parade show up at the Kane County Visitor Center at 6pm to sign up or go online and register early.\nBring the whole family as you watch the beautifully crafted parade entries float down Center Street, then head to the back parking lot of the Kanab Center to launch Wishing Lanterns.  Purchase your wishing lanterns at the event; write messages or wishes on your paper lanterns and send them to the sky. Watch your lanterns float to the heavens with a message to a loved one, or to the cosmos with your wishes attached.\n\nSchedule of Events at The Kanab Center, 20 N 100 E\n6:15pm &#8211; Refreshments at the Kanab Center\n6:45pm &#8211; Tree Lighting\n7:00pm -Parade\n7:30 pm &#8211; Lantern Launch begins (Kanab Center back parking lot)\nAll paper lanterns are 100% biodegradable and there is a local bounty on all lanterns found throughout town and the surrounding area to encourage a quick clean up. If you find lanterns and wish to turn them in for a $1 bounty, you can take them to the Kane County Office of Tourism Events (back door).  Check out the video below to see what our Christmas Light Parade and Festival is like.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2023-11-25 18:00:00',NULL,'{\"id\":1804,\"date\":\"2019-09-29T20:10:22\",\"date_gmt\":\"2019-09-29T20:10:22\",\"guid\":{\"rendered\":\"http:\\/\\/kanecounty.fluidstaging.com\\/?post_type=events&#038;p=1804\"},\"modified\":\"2023-09-26T13:23:20\",\"modified_gmt\":\"2023-09-26T19:23:20\",\"slug\":\"kanabs-christmas-light-parade-and-festival\",\"status\":\"publish\",\"type\":\"events\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/kanabs-christmas-light-parade-and-festival\\/\",\"title\":{\"rendered\":\"Kanab Christmas Light Parade and Festival\"},\"content\":{\"rendered\":\"\",\"protected\":false},\"excerpt\":{\"rendered\":\"\",\"protected\":false},\"author\":8,\"featured_media\":15116,\"template\":\"\",\"event_categories\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v18.6 - https:\\/\\/yoast.com\\/wordpress\\/plugins\\/seo\\/ -->\\n<title>Kanab Christmas Light Parade and Festival | Visit Southern Utah<\\/title>\\n<meta name=\\\"description\\\" content=\\\"Thanksgiving weekend we have the Christmas Light Parade and Festival. This is the best kickoff to the holiday season you will find anywhere in Southern Utah!\\\" \\/>\\n<meta name=\\\"robots\\\" content=\\\"index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/visitsouthernutah.com\\/events\\/kanabs-christmas-light-parade-and-festival\\/\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta property=\\\"og:title\\\" content=\\\"Kanab Christmas Light Parade and 