":\"\\/wp-content\\/uploads\\/2019\\/09\\/310966031_129372223212430_8545399586819958528_n-300x225.jpg\",\"medium-width\":300,\"medium-height\":225,\"medium_large\":\"\\/wp-content\\/uploads\\/2019\\/09\\/310966031_129372223212430_8545399586819958528_n-768x576.jpg\",\"medium_large-width\":768,\"medium_large-height\":576,\"large\":\"\\/wp-content\\/uploads\\/2019\\/09\\/310966031_129372223212430_8545399586819958528_n-1024x768.jpg\",\"large-width\":1024,\"large-height\":768,\"1536x1536\":\"\\/wp-content\\/uploads\\/2019\\/09\\/310966031_129372223212430_8545399586819958528_n-1536x1152.jpg\",\"1536x1536-width\":1536,\"1536x1536-height\":1152,\"2048x2048\":\"\\/wp-content\\/uploads\\/2019\\/09\\/310966031_129372223212430_8545399586819958528_n.jpg\",\"2048x2048-width\":2048,\"2048x2048-height\":1536}}],\"information_block_2\":\"\",\"related_events\":\"\",\"document_download\":false,\"recurrance\":\"\"},\"featured_image_url\":\"\\/wp-content\\/uploads\\/2019\\/07\\/glendale-apples-768x638.jpg\",\"_links\":{\"self\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\\/1768\"}],\"collection\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\"}],\"about\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/types\\/events\"}],\"author\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/users\\/8\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media\\/2974\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media?parent=1768\"}],\"wp:term\":[{\"taxonomy\":\"event_categories\",\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/event_categories?post=1768\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}',1,'2023-10-05 04:52:01','2023-10-05 04:52:01'),(66,'Grand Circle Trailfest','vsu','1757',158,'Trailfest is a 3-day/4-night trail running festival in the heart of North America&#8217;s most scenic national parks: Bryce Canyon, Zion, &amp; Horseshoe Bend.\n\n\nWhether you&#8217;re a hardcore ultramarathon runner or just getting into trail running, or maybe you&#8217;re just a supportive spouse (bring the whole family) or friend who doesn&#8217;t run, the Grand Circle Trailfest has something for you!\nEach day, we&#8217;ll run a segment of trail highlighting the natural landscape unique to that particular area. Each race is timed and you&#8217;ll receive a cumulative time at the end of the festival on Saturday. Top finishers for each course will be crowned at Trailfest Headquarters in Kanab, Utah at the end of each day.\nRegistration includes full participation in all three races, full Festival access, an on-site camping spot with a tent (yes, you&#8217;re welcome to bring your own tent if you prefer), and meal tickets for breakfast and dinner Thurs–Sat. (Additional meal tickets can be purchased on-site.) Festival activities are free for your non-running family and friends.\nBasic Itinerary\nWednesday (Oct. 4) &#8211; Check-in begins at noon\nThursday (Oct. 5) &#8211; Bryce Canyon race\nFriday (Oct. 6) &#8211; Zion race\nSaturday (Oct. 7) &#8211; Horseshoe Bend race\nSunday (Oct. 8) &#8211; Check-out by noon\nFollow us on Facebook or visit Grand Circle Trailfest to learn more or sign up.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2023-10-04 16:00:00','2023-10-08 17:00:00','{\"id\":1757,\"date\":\"2019-09-29T19:07:44\",\"date_gmt\":\"2019-09-29T19:07:44\",\"guid\":{\"rendered\":\"http:\\/\\/kanecounty.fluidstaging.com\\/?post_type=events&#038;p=1757\"},\"modified\":\"2023-08-30T15:49:27\",\"modified_gmt\":\"2023-08-30T21:49:27\",\"slug\":\"grand-circle-trailfest\",\"status\":\"publish\",\"type\":\"events\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/grand-circle-trailfest\\/\",\"title\":{\"rendered\":\"Grand Circle Trailfest\"},\"content\":{\"rend